import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.StringTokenizer;

public class G1 {

    static class IntList {
        private final ArrayList<Integer> data = new ArrayList<Integer>();

        boolean isEmpty() {
            return data.isEmpty();
        }

        int size() {
            return data.size();
        }

        int get(int index) {
            return data.get(index);
        }

        void clear() {
            data.clear();
        }

        void set(int index, int value) {
            data.set(index, value);
        }

        void insert(int index, int value) {
            data.add(index, value);
        }

        int delete(int index) {
            return data.remove(index);
        }

        void push(int value) {
            data.add(value);
        }

        int pop() {
            if (data.isEmpty()) {
                throw new NoSuchElementException();
            }
            return data.remove(data.size() - 1);
        }

        void unshift(int value) {
            data.add(0, value);
        }

        int shift() {
            if (data.isEmpty()) {
                throw new NoSuchElementException();
            }
            return data.remove(0);
        }
    }

    static final List<IntList> freeLists = new ArrayList<IntList>();

    static IntList takeList() {
        if (freeLists.isEmpty()) {
            return new IntList();
        } else {
            return freeLists.remove(freeLists.size() - 1);
        }
    }

    static void putList(IntList list) {
        list.clear();
        freeLists.add(list);
    }

    static class IntIntMap {
        static final int EMPTY = Integer.MIN_VALUE;
        final HashMap<Integer, Integer> map = new HashMap<Integer, Integer>();

        boolean isEmpty() {
            return map.isEmpty();
        }

        int size() {
            return map.size();
        }

        void clear() {
            map.clear();
        }

        boolean have(int key) {
            if (key == EMPTY) {
                throw new IllegalArgumentException();
            }
            return map.containsKey(key);
        }

        int get(int key, int default_) {
            if (key == EMPTY) {
                throw new IllegalArgumentException();
            }
            Integer v = map.get(key);
            return v == null ? default_ : v.intValue();
        }

        void set(int key, int value) {
            if (key == EMPTY) {
                throw new IllegalArgumentException();
            }
            map.put(key, value);
        }

        void delete(int key) {
            if (key == EMPTY) {
                throw new IllegalArgumentException();
            }
            map.remove(key);
        }
    }

    static int n, m;

    static IntList solve(int from, int to) {
        IntList res;
        if (from + 1 == to) {
            res = takeList();
            res.push(from);
            if (from + m > n) {
                res.push(n - from);
                res.push(from - n);
            }
            res.push(m);
            if (from > m) {
                res.push(n - from);
                res.push(from);
            }
            res.push(-from);
        } else {
            int mid = (from + to) >> 1;
            IntList a = solve(from, mid);
            IntList b = solve(mid, to);
            res = takeList();
            int aSize = a.size();
            int bSize = b.size();
            for (int i = 0;; i += 2) {
                int bFrom = i == 0 ? 0 : b.get(i - 1);
                int bTo = i == bSize - 1 ? n : b.get(i + 1);
                int bShift = b.get(i);
                int aFrom = bFrom + bShift;
                int aTo = bTo + bShift;
                int l = 0;
                int r = aSize - 1;
                while (l < r) {
                    int m = (((l + r) >> 2) << 1) + 1;
                    if (a.get(m) <= aFrom) {
                        l = m + 1;
                    } else {
                        r = m - 1;
                    }
                }
                int cur = l;
                while (true) {
                    res.push(bShift + a.get(cur));
                    ++cur;
                    if (cur == aSize) {
                        break;
                    }
                    int pos = a.get(cur);
                    if (pos >= aTo) {
                        break;
                    }
                    res.push(pos - bShift);
                    ++cur;
                }
                if (i == bSize - 1) {
                    break;
                }
                res.push(bTo);
            }
            putList(a);
            putList(b);
        }
        return res;
    }

    static void solve() throws Exception {
        n = scanInt();
        m = scanInt();
        int s = scanInt() - 1;
        long t = scanLong();
        for (int ct = (int) (t % n); ct != 0; ct--) {
            if (s < m) {
                s += ct;
                if (s >= n) {
                    s -= n;
                }
            } else {
                s -= ct;
                if (s < 0) {
                    s += n;
                }
            }
        }
        long cycles = t / n;
        if (cycles > 0) {
            IntList cycleSolve = solve(0, n);
            int csSize = cycleSolve.size();
            IntList cycleList = takeList();
            IntIntMap cycleMap = new IntIntMap();
            for (int it = 0;; it++) {
                if (it == cycles) {
                    break;
                }
                int prev = cycleMap.get(s, -1);
                if (prev >= 0) {
                    s = cycleList.get(prev + (int) ((cycles - prev) % (it - prev)));
                    break;
                }
                cycleList.push(s);
                cycleMap.set(s, it);
                int l = 0;
                int r = csSize - 1;
                while (l < r) {
                    int m = (((l + r) >> 2) << 1) + 1;
                    if (cycleSolve.get(m) <= s) {
                        l = m + 1;
                    } else {
                        r = m - 1;
                    }
                }
                s += cycleSolve.get(l);
            }
        }
        out.print(s + 1);
    }

    static int scanInt() throws IOException {
        return Integer.parseInt(scanString());
    }

    static long scanLong() throws IOException {
        return Long.parseLong(scanString());
    }

    static String scanString() throws IOException {
        while (tok == null || !tok.hasMoreTokens()) {
            tok = new StringTokenizer(in.readLine());
        }
        return tok.nextToken();
    }

    static BufferedReader in;
    static PrintWriter out;
    static StringTokenizer tok;

    public static void main(String[] args) {
        try {
            in = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out);
            solve();
            in.close();
            out.close();
        } catch (Throwable e) {
            e.printStackTrace();
            System.exit(1);
        }
    }
}
